var RangeFreqQuery = function(arr) {
    this.pos = new Map();
    for (let i = 0; i < arr.length; i++) {
        if (!this.pos.has(arr[i])) this.pos.set(arr[i], []);
        this.pos.get(arr[i]).push(i);
    }
};

RangeFreqQuery.prototype.query = function(left, right, value) {
    const idx = this.pos.get(value);
    if (idx === undefined) return 0;
    return this.upperBound(idx, right) - this.lowerBound(idx, left);
};

RangeFreqQuery.prototype.lowerBound = function(a, target) {
    let lo = 0, hi = a.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
};

RangeFreqQuery.prototype.upperBound = function(a, target) {
    let lo = 0, hi = a.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (a[mid] <= target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
};
